package audio

import "encoding/base64"

// mockAudioMP3Base64 contains a clean 2-second synthetic audio MP3
// so that mock synthesis produces valid, playable audio in all web browsers.
const mockAudioMP3Base64 = ""

func getMockPlayableMP3() []byte {
	data, _ := base64.StdEncoding.DecodeString(mockAudioMP3Base64)
	return data
}
